import { createHash } from "node:crypto"

/** A short, stable slug for a URL: the first 7 characters of its sha256, base64url. */
export function slugFor(url: string): string {
  return createHash("sha256").update(url).digest("base64url").slice(0, 7)
}


--- src/store.ts ---
import { slugFor } from "./slug.js"

/** Links in memory, by slug. */
export class LinkStore {
  private links = new Map<string, string>()

  /** Store a URL and return its slug. */
  put(url: string): string {
    const slug = slugFor(url)
    this.links.set(slug, url)
    return slug
  }

  /** The URL for a slug, or undefined. */
  get(slug: string): string | undefined {
    return this.links.get(slug)
  }
}
